-- Live drops for the bosses and rares of the 14 live classic dungeons and the elites and bosses of The Drowned City, the
-- Excavation Site and Krol'dok Stronghold: Wowhead's WoW Forever database (www.wowhead.com/forever), drop counts over kills
-- from its NPC pages (read 20 Nov). Changed: compared with our loot and written as our own rows with the measured chance; only
-- items the creature does not drop yet, directly or through its reference tables, go in.
-- What goes in:
--   * every WoW Forever item (recipes, plans, the new dungeon gear) on every creature in the list;
--   * on the classic bosses, the few classic items Forever added at 5% or more (Lady Anacondra, Lord Cobrahn, Commander
--     Springvale); their other classic drops already match the 1.12 tables;
--   * on the Forever creatures, everything they drop on live except rare and epic classic world drops below 0.5% (those come
--     from the world drop tables).
-- Left out: Waylaid Crates and Sealed Writs (handled with their own issues). Quest items (bound to a quest) only drop while
-- the quest is in the log. A creature with no loot id gets its own entry as loot id, unless another creature already uses it.
-- A row goes in only where the creature's loot id is its own entry and no other creature shares it, so no other creature's
-- loot changes. Safe to run more than once.
DROP TEMPORARY TABLE IF EXISTS `forever_drops_1121`;
CREATE TEMPORARY TABLE `forever_drops_1121` (`Entry` INT UNSIGNED NOT NULL, `Item` INT UNSIGNED NOT NULL, `Chance` FLOAT NOT NULL, `QuestRequired` TINYINT UNSIGNED NOT NULL, PRIMARY KEY (`Entry`,`Item`));

UPDATE `creature_template_difficulty` `d` SET `d`.`LootID`=`d`.`Entry` WHERE `d`.`DifficultyID`=0 AND `d`.`LootID`=0
  AND `d`.`Entry` IN (SELECT `Entry` FROM `forever_drops_1121`)
  AND NOT EXISTS (SELECT 1 FROM (SELECT `Entry`,`LootID` FROM `creature_template_difficulty` WHERE `LootID`<>0) `o` WHERE `o`.`LootID`=`d`.`Entry` AND `o`.`Entry`<>`d`.`Entry`);
SELECT `s`.`Entry`,0,`s`.`Item`,`s`.`Chance`,`s`.`QuestRequired`,1,0,1,1,'Wowhead Forever' FROM `forever_drops_1121` `s`
JOIN `creature_template_difficulty` `d` ON `d`.`Entry`=`s`.`Entry` AND `d`.`DifficultyID`=0 AND `d`.`LootID`=`s`.`Entry`
WHERE NOT EXISTS (SELECT 1 FROM `creature_loot_template` `x` WHERE `x`.`Entry`=`s`.`Entry` AND `x`.`ItemType`=0 AND `x`.`Item`=`s`.`Item`)
  AND NOT EXISTS (SELECT 1 FROM `creature_loot_template` `x` JOIN `reference_loot_template` `r` ON `r`.`Entry`=`x`.`Item`
    WHERE `x`.`Entry`=`s`.`Entry` AND `x`.`ItemType`=1 AND `r`.`ItemType`=0 AND `r`.`Item`=`s`.`Item`)
  AND NOT EXISTS (SELECT 1 FROM `creature_loot_template` `x` JOIN `reference_loot_template` `r` ON `r`.`Entry`=`x`.`Item`
    JOIN `reference_loot_template` `r2` ON `r2`.`Entry`=`r`.`Item`
    WHERE `x`.`Entry`=`s`.`Entry` AND `x`.`ItemType`=1 AND `r`.`ItemType`=1 AND `r2`.`ItemType`=0 AND `r2`.`Item`=`s`.`Item`)
  AND NOT EXISTS (SELECT 1 FROM `creature_template_difficulty` `o` WHERE `o`.`LootID`=`s`.`Entry` AND `o`.`Entry`<>`s`.`Entry`);
DROP TEMPORARY TABLE IF EXISTS `forever_drops_1121`;
